double monteCarloPi(int numPoints) {
  int insideCircle = 0;

  // Generate random points within unit square [-1, -1] x [1, 1]
  for (int i = 0; i < numPoints; ++i) {
    double randX = Random().nextDouble() * 2.0 - 1.0;
    double randY = Random().nextDouble() * 2.0 - 1.0;

    if ((randX**2 + randY**2 <= 1)) {   // Check whether point lies in circle or not 
      insideCircle += 1;
    }

  }

  return MathUtils.PI(insideCircle / numPoints);
}

